<header class="module-page__header"><div><nav class="breadcrumb" aria-label="Breadcrumb"><a href="<?=e(url('/admin/dashboard'))?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Roles &amp; Permissions</span></nav><h1>Roles &amp; Permissions</h1><p>Control what each type of user can see and change.</p></div></header>
<section class="module-card roles-create-card"><header class="module-card__header"><div><h2>Create Role</h2><p>Add a staff role, then grant it permissions.</p></div></header><div class="module-card__body"><form method="post" action="<?=e(url('/admin/roles'))?>" class="module-form"><?=csrf_field()?><div class="module-field"><label for="name">Role Name</label><input class="module-input" id="name" name="name" type="text" required maxlength="80" placeholder="e.g. Librarian"></div><div class="module-field"><label for="description">Description</label><input class="module-input" id="description" name="description" type="text" maxlength="255" placeholder="Optional"></div><div class="filter-actions"><button class="btn btn--primary" type="submit"><i data-lucide="plus"></i>Create Role</button></div></form></div></section>
