<?php foreach($roles as $r): $sys=(int)$r['is_system']===1; ?><tr><td><div class="record-identity"><span class="record-identity__avatar" aria-hidden="true"><?=e(strtoupper(substr((string)$r['name'],0,1)))?></span><span><strong><?=e($r['name'])?></strong><?php if($r['description']):?><small><?=e($r['description'])?></small><?php endif?></span></div></td><td><code><?=e($r['slug'])?></code></td><td><span class="status-badge"><?=$sys?'Built-in':'Custom'?></span></td><td><?=$r['slug']==='admin'?'Full access':(int)$r['permission_count']?></td><td><?=(int)$r['user_count']?></td><td><div class="row-actions"><a class="class-action-button" href="<?=e(url('/admin/roles/'.(int)$r['id'].'/edit'))?>" aria-label="Manage <?=e($r['name'])?>" title="Manage role"><i data-lucide="pencil"></i></a><?php if(!$sys && (int)$r['user_count']===0):?><form method="post" action="<?=e(url('/admin/roles/'.(int)$r['id'].'/delete'))?>"><?=csrf_field()?><button class="class-action-button class-action-button--danger" type="submit" aria-label="Delete <?=e($r['name'])?>" title="Delete role"><i data-lucide="trash-2"></i></button></form><?php endif?></div></td></tr><?php endforeach; ?>
<?php if(!$roles):?><tr><td colspan="6"><div class="compact-empty"><h3>No roles yet</h3><p>Create a role to define staff access.</p></div></td></tr><?php endif?>
</tbody></table></div></div></section>
